//! Ring-0 wire encoders (TPM 2.0 `TPM2_Quote`, NSM `Attestation` CBOR).
//!
//! Pure byte arithmetic: no syscalls, no heap, no `target_os` gate. Extracted
//! from `linux_tpm2` / `aws_nitro` so the golden vectors run on every host
//! (CLAIM-RING0-010 / CLAIM-RING0-011, TD-RING0-001 option B).
//!
//! The golden vectors below are written by hand from TCG TPM 2.0 Part 3 §16.4 /
//! Part 2 §10.9 and RFC 8949 §4.2.1, not generated by the code under test.

/// `TPM_ST_SESSIONS`: the command carries an authorization area.
pub const TPM_ST_SESSIONS: u16 = 0x8002;
/// `TPM_CC_Quote`.
pub const TPM_CC_QUOTE: u32 = 0x0000_0158;
/// Total length of the `TPM2_Quote` command.
pub const TPM2_QUOTE_CMD_LEN: usize = 73;
/// Total length of the NSM `Attestation` CBOR request.
pub const NSM_ATTESTATION_REQ_LEN: usize = 73;

/// Builds the binary `TPM2_Quote` packet with `qualifyingData` = causal digest
/// and a SHA-256 selection of PCR 0, 7 and 14.
#[must_use]
pub fn build_quote_command(ak_handle: u32, qualifying_digest: &[u8; 32]) -> [u8; TPM2_QUOTE_CMD_LEN] {
    let mut cmd = [0u8; TPM2_QUOTE_CMD_LEN];
    cmd[0..2].copy_from_slice(&TPM_ST_SESSIONS.to_be_bytes());
    cmd[2..6].copy_from_slice(&(TPM2_QUOTE_CMD_LEN as u32).to_be_bytes());
    cmd[6..10].copy_from_slice(&TPM_CC_QUOTE.to_be_bytes());
    cmd[10..14].copy_from_slice(&ak_handle.to_be_bytes());

    // Authorization area: null password session TPM_RS_PW (0x40000009), 9 bytes.
    cmd[14..18].copy_from_slice(&9u32.to_be_bytes());
    cmd[18..22].copy_from_slice(&0x4000_0009u32.to_be_bytes());
    cmd[22..24].copy_from_slice(&0u16.to_be_bytes()); // empty nonce
    cmd[24] = 0x01; // continueSession
    cmd[25..27].copy_from_slice(&0u16.to_be_bytes()); // empty hmac

    // qualifyingData: TPM2B_DATA with the 32-byte causal digest.
    cmd[27..29].copy_from_slice(&32u16.to_be_bytes());
    cmd[29..61].copy_from_slice(qualifying_digest);

    // inScheme: TPM_ALG_NULL (no details follow) -> AK default scheme.
    cmd[61..63].copy_from_slice(&0x0010u16.to_be_bytes());

    // TPML_PCR_SELECTION: one SHA-256 bank, PCR 0, 7 and 14.
    cmd[63..67].copy_from_slice(&1u32.to_be_bytes());
    cmd[67..69].copy_from_slice(&0x000Bu16.to_be_bytes());
    cmd[69] = 3; // sizeofSelect
    cmd[70] = 0b1000_0001; // PCR 0 and PCR 7
    cmd[71] = 0b0100_0000; // PCR 14
    cmd[72] = 0x00;
    cmd
}

/// Static, heap-free CBOR for `{"Attestation": {"user_data": bstr(32), "nonce": bstr(8)}}`.
#[must_use]
pub fn encode_cbor_attestation_req(digest: &[u8; 32], tick: u64) -> [u8; NSM_ATTESTATION_REQ_LEN] {
    let mut req = [0u8; NSM_ATTESTATION_REQ_LEN];
    req[0] = 0xA1; // map(1)
    req[1] = 0x6B; // text(11)
    req[2..13].copy_from_slice(b"Attestation");
    req[13] = 0xA2; // map(2)
    req[14] = 0x69; // text(9)
    req[15..24].copy_from_slice(b"user_data");
    req[24] = 0x58; // bytes, one-byte length (32 >= 24)
    req[25] = 0x20;
    req[26..58].copy_from_slice(digest);
    req[58] = 0x65; // text(5)
    req[59..64].copy_from_slice(b"nonce");
    req[64] = 0x48; // bytes(8), shortest form (RFC 8949 §4.2.1)
    req[65..73].copy_from_slice(&tick.to_be_bytes());
    req
}

#[cfg(test)]
mod golden {
    use super::*;

    const AK_HANDLE: u32 = 0x8100_0001;
    const TICK: u64 = 42;
    const DIGEST: [u8; 32] = [
        0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E,
        0x0F, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D,
        0x1E, 0x1F,
    ];

    /// Frozen TPM2_Quote vector (73 bytes, TPM_ST_SESSIONS + null PW session).
    const EXPECTED_QUOTE: [u8; 73] = [
        0x80, 0x02, 0x00, 0x00, 0x00, 0x49, 0x00, 0x00, 0x01, 0x58, // header
        0x81, 0x00, 0x00, 0x01, // keyHandle
        0x00, 0x00, 0x00, 0x09, 0x40, 0x00, 0x00, 0x09, 0x00, 0x00, 0x01, 0x00, 0x00, // auth area
        0x00, 0x20, // qualifyingData.size
        0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E,
        0x0F, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D,
        0x1E, 0x1F, // digest
        0x00, 0x10, // inScheme = TPM_ALG_NULL
        0x00, 0x00, 0x00, 0x01, 0x00, 0x0B, 0x03, 0x81, 0x40, 0x00, // TPML_PCR_SELECTION
    ];

    /// Frozen NSM vector (73 bytes, canonical CBOR).
    const EXPECTED_NSM: [u8; 73] = [
        0xA1, 0x6B, 0x41, 0x74, 0x74, 0x65, 0x73, 0x74, 0x61, 0x74, 0x69, 0x6F, 0x6E, 0xA2, 0x69,
        0x75, 0x73, 0x65, 0x72, 0x5F, 0x64, 0x61, 0x74, 0x61, 0x58, 0x20, 0x00, 0x01, 0x02, 0x03,
        0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x10, 0x11, 0x12,
        0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1A, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F, 0x65, 0x6E,
        0x6F, 0x6E, 0x63, 0x65, 0x48, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,
    ];

    #[test]
    fn tpm2_quote_matches_golden_vector() {
        assert_eq!(build_quote_command(AK_HANDLE, &DIGEST), EXPECTED_QUOTE);
    }

    #[test]
    fn tpm2_quote_command_size_field_is_self_consistent() {
        let q = build_quote_command(0x8100_00AA, &DIGEST);
        assert_eq!(u32::from_be_bytes([q[2], q[3], q[4], q[5]]) as usize, q.len());
        assert_eq!(&q[10..14], &[0x81, 0x00, 0x00, 0xAA]);
    }

    #[test]
    fn tpm2_quote_auth_area_size_covers_exactly_the_session() {
        let q = build_quote_command(AK_HANDLE, &DIGEST);
        // authorizationSize = 9 = handle(4) + nonce(2) + attrs(1) + hmac(2).
        assert_eq!(u32::from_be_bytes([q[14], q[15], q[16], q[17]]), 9);
        assert_eq!(&q[18..22], &[0x40, 0x00, 0x00, 0x09]);
    }

    #[test]
    fn tpm2_quote_binds_digest_once_as_qualifying_data() {
        let q = build_quote_command(AK_HANDLE, &DIGEST);
        assert_eq!(&q[27..29], &[0x00, 0x20]);
        assert_eq!(&q[29..61], &DIGEST[..]);
        assert_eq!(q.windows(32).filter(|w| *w == DIGEST).count(), 1);
    }

    #[test]
    fn tpm2_quote_selects_pcr_0_7_14_in_sha256() {
        let q = build_quote_command(AK_HANDLE, &DIGEST);
        assert_eq!(&q[63..67], &[0, 0, 0, 1]);
        assert_eq!(&q[67..69], &[0x00, 0x0B]);
        assert_eq!(&q[69..73], &[0x03, 0x81, 0x40, 0x00]);
    }

    #[test]
    fn nsm_attestation_matches_golden_vector() {
        assert_eq!(encode_cbor_attestation_req(&DIGEST, TICK), EXPECTED_NSM);
    }

    #[test]
    fn nsm_attestation_is_deterministic_and_canonical() {
        let a = encode_cbor_attestation_req(&DIGEST, TICK);
        assert_eq!(a, encode_cbor_attestation_req(&DIGEST, TICK));
        assert_eq!(a[64], 0x48, "nonce must use shortest-form bstr(8)");
        assert_eq!(&a[65..73], &TICK.to_be_bytes());
    }

    #[test]
    fn nsm_attestation_tick_changes_only_the_nonce() {
        let a = encode_cbor_attestation_req(&DIGEST, 1);
        let b = encode_cbor_attestation_req(&DIGEST, 2);
        assert_eq!(a[..65], b[..65]);
        assert_ne!(a[65..], b[65..]);
    }
}
